definition:
CREATE OR REPLACE FUNCTION public._export_assert_caller(p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_org uuid;
  v_is_tenant_only boolean;
BEGIN
  -- SQL editor / service_role: no end-user JWT; org still filtered by p_organization_id.
  IF auth.uid() IS NULL THEN
    IF public._export_is_admin_context() THEN
      IF NOT EXISTS (SELECT 1 FROM organizations WHERE id = p_organization_id) THEN
        RAISE EXCEPTION 'unknown organization_id: %', p_organization_id USING ERRCODE = '22023';
      END IF;
      RETURN;
    END IF;
    RAISE EXCEPTION 'forbidden: not authenticated (use app session JWT, or run as postgres/service_role in SQL editor)'
      USING ERRCODE = '42501';
  END IF;

  v_caller_org := COALESCE(
    public.get_user_org_id(auth.uid()),
    (SELECT organization_id FROM profiles WHERE id = auth.uid() LIMIT 1)
  );

  IF v_caller_org IS NULL OR v_caller_org <> p_organization_id THEN
    RAISE EXCEPTION 'forbidden: org mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM user_roles ur
    WHERE ur.user_id = auth.uid() AND ur.role = 'tenant'::app_role
  ) AND NOT EXISTS (
    SELECT 1 FROM user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.role IN (
        'super_admin'::app_role,
        'org_admin'::app_role,
        'property_manager'::app_role,
        'employee'::app_role
      )
  ) INTO v_is_tenant_only;

  IF v_is_tenant_only THEN
    RAISE EXCEPTION 'forbidden: tenant role cannot export org datasets' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._export_resolve_view(p_entity text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_view text;
BEGIN
  SELECT view_name INTO v_view
  FROM export_entity_registry
  WHERE entity_key = p_entity;

  IF v_view IS NULL THEN
    RAISE EXCEPTION 'unknown export entity: %', p_entity USING ERRCODE = '22023';
  END IF;

  RETURN v_view;
END;
$function$

CREATE OR REPLACE FUNCTION public.build_invoice_lines(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_inv         invoices%ROWTYPE;
    v_lines       jsonb := '[]'::jsonb;
    v_total       numeric;
    v_ar_id       uuid;
    v_rent_id     uuid;
    v_eb_id       uuid;
    v_other_id    uuid;
    v_late_id     uuid;
    v_onb_id      uuid;
    v_exit_id     uuid;
    v_dep_id      uuid;
    v_remainder_account uuid;
    v_rent        numeric := 0;
    v_eb          numeric := 0;
    v_other       numeric := 0;
    v_late        numeric := 0;
    v_components  numeric := 0;
    v_remainder   numeric := 0;
    v_scale       numeric;
    v_credit_sum  numeric := 0;
    v_drift       numeric;
BEGIN
    SELECT * INTO v_inv FROM invoices WHERE id = p_invoice_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invoice % not found', p_invoice_id;
    END IF;

    v_total := COALESCE(v_inv.total_amount, 0);
    IF v_total <= 0 THEN
        RETURN '[]'::jsonb;
    END IF;

    v_ar_id    := coa_id(v_inv.organization_id, '1200');
    v_rent_id  := coa_id(v_inv.organization_id, '4100');
    v_eb_id    := coa_id(v_inv.organization_id, '4200');
    v_other_id := coa_id(v_inv.organization_id, '4900');
    v_late_id  := coa_id(v_inv.organization_id, '4400');
    v_onb_id   := coa_id(v_inv.organization_id, '4300');
    v_exit_id  := coa_id(v_inv.organization_id, '4500');
    v_dep_id   := coa_id(v_inv.organization_id, '2100');

    IF v_inv.invoice_type = 'additional_deposit' THEN
        RETURN jsonb_build_array(
            jsonb_build_object(
                'account_id',   v_ar_id,
                'debit',        v_total,
                'party_kind',   'tenant',
                'party_id',     v_inv.tenant_id,
                'allotment_id', v_inv.allotment_id,
                'property_id',  v_inv.property_id,
                'apartment_id', v_inv.apartment_id,
                'bed_id',       v_inv.bed_id,
                'memo',         'Additional deposit invoice ' || COALESCE(v_inv.invoice_number, '')
            ),
            jsonb_build_object(
                'account_id',   v_dep_id,
                'credit',       v_total,
                'party_kind',   'tenant',
                'party_id',     v_inv.tenant_id,
                'allotment_id', v_inv.allotment_id,
                'memo',         'Deposit top-up'
            )
        );
    END IF;

    IF v_inv.invoice_type = 'exit_charge' THEN
        RETURN jsonb_build_array(
            jsonb_build_object(
                'account_id',   v_ar_id,
                'debit',        v_total,
                'party_kind',   'tenant',
                'party_id',     v_inv.tenant_id,
                'allotment_id', v_inv.allotment_id,
                'property_id',  v_inv.property_id,
                'apartment_id', v_inv.apartment_id,
                'bed_id',       v_inv.bed_id,
                'memo',         'Exit charges ' || COALESCE(v_inv.invoice_number, '')
            ),
            jsonb_build_object(
                'account_id',   v_exit_id,
                'credit',       v_total,
                'property_id',  v_inv.property_id,
                'memo',         'Exit charges'
            )
        );
    END IF;

    -- DEBIT: AR for total
    v_lines := jsonb_build_array(jsonb_build_object(
        'account_id',   v_ar_id,
        'debit',        v_total,
        'party_kind',   'tenant',
        'party_id',     v_inv.tenant_id,
        'allotment_id', v_inv.allotment_id,
        'property_id',  v_inv.property_id,
        'apartment_id', v_inv.apartment_id,
        'bed_id',       v_inv.bed_id,
        'memo',         COALESCE(v_inv.invoice_number, v_inv.id::text) ||
                        ' (' || COALESCE(v_inv.billing_month, '') || ')'
    ));

    -- ✱ FIX: Electricity Income = actual electricity_amount + estimated_eb.
    -- Both belong to Electricity Income (4200). Previously estimated_eb was
    -- only used as a fallback when electricity_amount was 0, causing it to
    -- spill into the 4900 (Other Income) remainder bucket.
    v_rent  := COALESCE(v_inv.rent_amount, 0);
    v_eb    := COALESCE(v_inv.electricity_amount, 0) + COALESCE(v_inv.estimated_eb, 0);
    v_other := COALESCE(v_inv.other_charges, 0);
    v_late  := COALESCE(v_inv.late_fee, 0);

    v_components := v_rent + v_eb + v_other + v_late;

    -- Components OVERSHOOT total → trim proportionally
    IF v_components > v_total + 0.005 AND v_components > 0 THEN
        v_scale := v_total / v_components;
        v_rent  := ROUND(v_rent  * v_scale, 2);
        v_eb    := ROUND(v_eb    * v_scale, 2);
        v_other := ROUND(v_other * v_scale, 2);
        v_late  := ROUND(v_late  * v_scale, 2);
        v_components := v_rent + v_eb + v_other + v_late;
    END IF;

    v_remainder := v_total - v_components;

    IF v_inv.invoice_type = 'onboarding' THEN
        v_remainder_account := v_onb_id;
    ELSE
        v_remainder_account := v_other_id;
    END IF;

    IF v_rent > 0 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_rent_id, 'credit', v_rent,
            'property_id', v_inv.property_id, 'apartment_id', v_inv.apartment_id, 'bed_id', v_inv.bed_id,
            'memo', CASE WHEN v_inv.invoice_type = 'onboarding'
                         THEN 'Prorated rent (onboarding)'
                         ELSE 'Rent ' || COALESCE(v_inv.billing_month, '')
                    END
        ));
        v_credit_sum := v_credit_sum + v_rent;
    END IF;

    IF v_eb > 0 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_eb_id, 'credit', v_eb,
            'property_id', v_inv.property_id, 'apartment_id', v_inv.apartment_id, 'bed_id', v_inv.bed_id,
            'memo', 'Electricity (actual + estimated) ' || COALESCE(v_inv.billing_month, '')
        ));
        v_credit_sum := v_credit_sum + v_eb;
    END IF;

    IF v_other > 0 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_other_id, 'credit', v_other,
            'property_id', v_inv.property_id,
            'memo', 'Other charges ' || COALESCE(v_inv.billing_month, '')
        ));
        v_credit_sum := v_credit_sum + v_other;
    END IF;

    IF v_late > 0 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_late_id, 'credit', v_late,
            'property_id', v_inv.property_id,
            'memo', 'Late fee ' || COALESCE(v_inv.billing_month, '')
        ));
        v_credit_sum := v_credit_sum + v_late;
    END IF;

    IF v_remainder > 0.005 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_remainder_account, 'credit', v_remainder,
            'property_id', v_inv.property_id,
            'memo', CASE WHEN v_inv.invoice_type = 'onboarding'
                         THEN 'Onboarding fees & charges'
                         ELSE 'Other (unspecified) — ' || COALESCE(v_inv.billing_month, '')
                    END
        ));
        v_credit_sum := v_credit_sum + v_remainder;
    END IF;

    v_drift := v_total - v_credit_sum;
    IF ABS(v_drift) > 0.005 THEN
        IF v_drift > 0 THEN
            v_lines := v_lines || jsonb_build_array(jsonb_build_object(
                'account_id', v_other_id, 'credit', v_drift,
                'property_id', v_inv.property_id,
                'memo', 'Rounding adjustment'
            ));
        ELSE
            v_lines := v_lines || jsonb_build_array(jsonb_build_object(
                'account_id', v_other_id, 'debit', ABS(v_drift),
                'property_id', v_inv.property_id,
                'memo', 'Rounding adjustment'
            ));
        END IF;
    END IF;

    IF v_credit_sum < 0.005 AND ABS(v_drift) <= 0.005 THEN
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id', v_remainder_account, 'credit', v_total,
            'property_id', v_inv.property_id,
            'memo', 'Unspecified income (no components on invoice)'
        ));
    END IF;

    RETURN v_lines;
END $function$

CREATE OR REPLACE FUNCTION public.delete_journal_entries_on_source_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ids uuid[];
  v_source_table text := TG_ARGV[0];
BEGIN
  SELECT array_agg(id) INTO v_ids
  FROM journal_entries
  WHERE source_table = v_source_table AND source_id = OLD.id;

  IF v_ids IS NOT NULL THEN
    DELETE FROM journal_lines   WHERE journal_entry_id = ANY(v_ids);
    DELETE FROM journal_entries WHERE id               = ANY(v_ids);
  END IF;
  RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_journal_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_diff numeric;
    v_id   uuid;
BEGIN
    v_id := COALESCE(NEW.id, OLD.id);

    SELECT COALESCE(SUM(debit) - SUM(credit), 0)
      INTO v_diff
      FROM journal_lines
     WHERE journal_entry_id = v_id;

    -- Allow header-only inserts that haven't yet written lines (helper functions
    -- write lines after creating the header within the same transaction)
    IF NOT EXISTS (SELECT 1 FROM journal_lines WHERE journal_entry_id = v_id) THEN
        RETURN NEW;
    END IF;

    IF ABS(v_diff) > 0.005 THEN
        RAISE EXCEPTION
          'Journal entry % is unbalanced by %. Debits must equal credits.',
          v_id, v_diff;
    END IF;

    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.export_dataset_batch(p_organization_id uuid, p_entity text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_view text;
  v_result jsonb;
  v_limit integer;
  v_offset integer;
BEGIN
  PERFORM public._export_assert_caller(p_organization_id);
  v_view := public._export_resolve_view(p_entity);

  v_limit  := LEAST(GREATEST(COALESCE(p_limit, 1000), 1), 5000);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);

  EXECUTE format(
    $q$
      SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.id), '[]'::jsonb)
      FROM (
        SELECT *
        FROM public.%I
        WHERE organization_id = $1
        ORDER BY id
        OFFSET $2
        LIMIT $3
      ) t
    $q$,
    v_view
  ) INTO v_result USING p_organization_id, v_offset, v_limit;

  RETURN jsonb_build_object(
    'entity', p_entity,
    'offset', v_offset,
    'limit', v_limit,
    'rows', COALESCE(v_result, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.export_dataset_count(p_organization_id uuid, p_entity text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_view text;
  v_count bigint;
BEGIN
  PERFORM public._export_assert_caller(p_organization_id);
  v_view := public._export_resolve_view(p_entity);

  EXECUTE format(
    'SELECT count(*)::bigint FROM public.%I WHERE organization_id = $1',
    v_view
  ) INTO v_count USING p_organization_id;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_owner_payment_journal_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bill_date date;
BEGIN
  IF NEW.source_table IS DISTINCT FROM 'owner_payments' OR NEW.source_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT bill_date
    INTO v_bill_date
    FROM owner_payments
   WHERE id = NEW.source_id;

  IF v_bill_date IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.entry_date := v_bill_date;
  NEW.period     := to_char(v_bill_date, 'YYYY-MM');

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_journal_entry(p_org uuid, p_date date, p_description text, p_source_table text, p_source_id uuid, p_lines jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_is_reversal_of uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_je_id uuid;
    v_line  jsonb;
    v_idx   int := 0;
    v_total_debit  numeric := 0;
    v_total_credit numeric := 0;
BEGIN
    IF p_lines IS NULL OR jsonb_array_length(p_lines) < 2 THEN
        RAISE EXCEPTION 'A journal entry must have at least 2 lines (got %)',
            COALESCE(jsonb_array_length(p_lines), 0);
    END IF;

    INSERT INTO journal_entries (
        organization_id, entry_date, period, description,
        source_table, source_id, metadata, is_reversal_of
    ) VALUES (
        p_org, p_date, date_to_period(p_date), p_description,
        p_source_table, p_source_id, p_metadata, p_is_reversal_of
    )
    RETURNING id INTO v_je_id;

    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        v_idx := v_idx + 1;

        INSERT INTO journal_lines (
            journal_entry_id, organization_id, account_id,
            debit, credit,
            party_kind, party_id, allotment_id,
            property_id, apartment_id, bed_id,
            memo, line_no
        ) VALUES (
            v_je_id, p_org, (v_line->>'account_id')::uuid,
            COALESCE((v_line->>'debit')::numeric,  0),
            COALESCE((v_line->>'credit')::numeric, 0),
            NULLIF(v_line->>'party_kind','')::party_kind,
            NULLIF(v_line->>'party_id','')::uuid,
            NULLIF(v_line->>'allotment_id','')::uuid,
            NULLIF(v_line->>'property_id','')::uuid,
            NULLIF(v_line->>'apartment_id','')::uuid,
            NULLIF(v_line->>'bed_id','')::uuid,
            v_line->>'memo',
            v_idx
        );

        v_total_debit  := v_total_debit  + COALESCE((v_line->>'debit')::numeric, 0);
        v_total_credit := v_total_credit + COALESCE((v_line->>'credit')::numeric, 0);
    END LOOP;

    -- Sanity check (the deferred trigger also checks this, but fail fast here for clearer errors)
    IF ABS(v_total_debit - v_total_credit) > 0.005 THEN
        RAISE EXCEPTION
          'Unbalanced journal entry: debits=% credits=% diff=%',
          v_total_debit, v_total_credit, v_total_debit - v_total_credit;
    END IF;

    RETURN v_je_id;
END $function$

CREATE OR REPLACE FUNCTION public.reconcile_exit_settlement(p_allotment_id uuid, p_exit_date date, p_refund_amount numeric DEFAULT NULL::numeric, p_refund_date date DEFAULT NULL::date, p_refund_bank_id uuid DEFAULT NULL::uuid, p_refund_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  DECLARE v_ta tenant_allotments%ROWTYPE; v_org uuid; v_dues numeric; v_deposit numeric;
    v_excess numeric; v_refund numeric; v_settle_id uuid;
  BEGIN
    SELECT * INTO v_ta FROM tenant_allotments WHERE id=p_allotment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Allotment % not found', p_allotment_id; END IF;
    IF v_ta.staying_status <> 'Exited' THEN RAISE EXCEPTION 'Allotment % is % (must be Exited)', p_allotment_id, v_ta.staying_status; END IF;
    v_org := v_ta.organization_id;
    IF v_ta.actual_exit_date IS NULL THEN UPDATE tenant_allotments SET actual_exit_date=p_exit_date WHERE id=p_allotment_id; END IF;

    SELECT COALESCE(SUM(jl.debit)-SUM(jl.credit),0) INTO v_dues
    FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_entry_id JOIN coa_accounts a ON a.id=jl.account_id
    WHERE jl.allotment_id=p_allotment_id AND a.code='1200'
      AND je.source_table IS DISTINCT FROM 'deposit_settlements'
      AND je.is_reversal_of IS NULL AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id);

    IF v_dues < -0.5 THEN
      v_excess := round(abs(v_dues));
      INSERT INTO tenant_adjustments (organization_id,tenant_id,allotment_id,adjustment_type,category,amount,reason,
        billing_month,adjustment_date,property_id,apartment_id,bed_id,reference_type,reference_id)
      VALUES (v_org,v_ta.tenant_id,p_allotment_id,'credit_note','rental_adjustment',v_excess,
        'Exit reconciliation: excess rent credited to clear ledger',
        to_char(p_exit_date,'YYYY-MM'),p_exit_date,v_ta.property_id,v_ta.apartment_id,v_ta.bed_id,
        'exit_excess_clearance',p_allotment_id);
      SELECT COALESCE(SUM(jl.debit)-SUM(jl.credit),0) INTO v_dues
      FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_entry_id JOIN coa_accounts a ON a.id=jl.account_id
      WHERE jl.allotment_id=p_allotment_id AND a.code='1200'
        AND je.source_table IS DISTINCT FROM 'deposit_settlements'
        AND je.is_reversal_of IS NULL AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id);
    END IF;

    SELECT COALESCE(SUM(jl.credit)-SUM(jl.debit),0) INTO v_deposit
    FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_entry_id JOIN coa_accounts a ON a.id=jl.account_id
    WHERE jl.allotment_id=p_allotment_id AND a.code IN ('2100','2400')
      AND je.source_table IS DISTINCT FROM 'deposit_settlements'
      AND je.is_reversal_of IS NULL AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id);

    v_refund := COALESCE(p_refund_amount, GREATEST(v_deposit - GREATEST(v_dues,0), 0));

    UPDATE deposit_settlements SET deposit_amount=v_deposit, pending_rent=GREATEST(v_dues,0), pending_eb=0,
      total_deductions=GREATEST(v_dues,0), refund_amount=v_refund, settlement_date=p_exit_date,
      status='completed', is_deleted=FALSE
     WHERE allotment_id=p_allotment_id AND COALESCE(is_deleted,FALSE)=FALSE
     RETURNING id INTO v_settle_id;
    IF v_settle_id IS NULL THEN
      INSERT INTO deposit_settlements (organization_id,tenant_id,allotment_id,deposit_amount,pending_rent,pending_eb,
        damages,other_deductions,total_deductions,refund_amount,settlement_date,status)
      VALUES (v_org,v_ta.tenant_id,p_allotment_id,v_deposit,GREATEST(v_dues,0),0,0,0,GREATEST(v_dues,0),v_refund,p_exit_date,'completed')
      RETURNING id INTO v_settle_id;
    END IF;

    UPDATE tenant_exits SET exit_date=p_exit_date, advance_held=v_deposit, pending_rent=v_dues,
      total_deductions=GREATEST(v_dues,0), refund_due=v_refund, refund_status='completed',
      refund_date=COALESCE(p_refund_date,p_exit_date), refund_bank_id=p_refund_bank_id, refund_reference=p_refund_reference
     WHERE allotment_id=p_allotment_id;
    IF NOT FOUND THEN
      INSERT INTO tenant_exits (organization_id,tenant_id,allotment_id,bed_id,exit_date,pending_rent,
        total_deductions,advance_held,refund_due,refund_status,refund_date,refund_bank_id,refund_reference)
      VALUES (v_org,v_ta.tenant_id,p_allotment_id,v_ta.bed_id,p_exit_date,v_dues,GREATEST(v_dues,0),v_deposit,v_refund,
        'completed',COALESCE(p_refund_date,p_exit_date),p_refund_bank_id,p_refund_reference);
    END IF;

    RETURN jsonb_build_object('dues',round(v_dues),'deposit_held',round(v_deposit),'refund',round(v_refund),
      'balanced',(abs(v_deposit-(LEAST(GREATEST(v_dues,0),v_deposit)+v_refund))<=1));
  END; $function$

CREATE OR REPLACE FUNCTION public.replace_invoices_atomic(p_org_id uuid, p_billing_month text, p_allotment_ids uuid[], p_invoices jsonb, p_line_items jsonb, p_eb_shares jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_ids uuid[];
  v_inserted_ids uuid[];
  v_inv jsonb;
  v_new_id uuid;
  v_li jsonb;
  v_es jsonb;
  v_inv_index int;
BEGIN
  -- Validate inputs
  IF p_allotment_ids IS NULL OR array_length(p_allotment_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'allotment_ids must be a non-empty array';
  END IF;

  -- Step 1: Find existing invoice IDs scoped to the given allotments
  SELECT array_agg(id) INTO v_existing_ids
  FROM invoices
  WHERE organization_id = p_org_id
    AND billing_month = p_billing_month
    AND is_deleted = false
    AND allotment_id = ANY(p_allotment_ids);

  -- Step 2: Delete related records then invoices (all in this transaction)
  IF v_existing_ids IS NOT NULL AND array_length(v_existing_ids, 1) > 0 THEN
    DELETE FROM invoice_line_items WHERE invoice_id = ANY(v_existing_ids);
    DELETE FROM eb_tenant_shares WHERE invoice_id = ANY(v_existing_ids);
    DELETE FROM invoices WHERE id = ANY(v_existing_ids);
  END IF;

  -- Step 3: Insert new invoices and collect their IDs in order
  v_inserted_ids := ARRAY[]::uuid[];
  FOR v_inv IN SELECT * FROM jsonb_array_elements(p_invoices)
  LOOP
    INSERT INTO invoices (
      organization_id, tenant_id, property_id, apartment_id, bed_id,
      allotment_id, invoice_number, billing_month, rent_amount,
      electricity_amount, estimated_eb, late_fee, other_charges,
      total_amount, invoice_date, due_date, status, balance, amount_paid, invoice_type, is_deleted
    ) VALUES (
      (v_inv->>'organization_id')::uuid,
      (v_inv->>'tenant_id')::uuid,
      (v_inv->>'property_id')::uuid,
      (v_inv->>'apartment_id')::uuid,
      (v_inv->>'bed_id')::uuid,
      (v_inv->>'allotment_id')::uuid,
      v_inv->>'invoice_number',
      v_inv->>'billing_month',
      (v_inv->>'rent_amount')::numeric,
      (v_inv->>'electricity_amount')::numeric,
      COALESCE((v_inv->>'estimated_eb')::numeric, 0),
      (v_inv->>'late_fee')::numeric,
      (v_inv->>'other_charges')::numeric,
      (v_inv->>'total_amount')::numeric,
      (v_inv->>'invoice_date')::date,
      (v_inv->>'due_date')::date,
      COALESCE(v_inv->>'status', 'pending'),
      (v_inv->>'balance')::numeric,
      COALESCE((v_inv->>'amount_paid')::numeric, 0),
      COALESCE(v_inv->>'invoice_type', 'regular'),
      false
    ) RETURNING id INTO v_new_id;
    v_inserted_ids := array_append(v_inserted_ids, v_new_id);
  END LOOP;

  -- Step 4: Insert line items using invoice_index to resolve invoice_id
  IF p_line_items IS NOT NULL AND jsonb_array_length(p_line_items) > 0 THEN
    FOR v_li IN SELECT * FROM jsonb_array_elements(p_line_items)
    LOOP
      v_inv_index := (v_li->>'invoice_index')::int;
      INSERT INTO invoice_line_items (
        invoice_id, organization_id, line_type, description, amount, metadata
      ) VALUES (
        v_inserted_ids[v_inv_index + 1],
        p_org_id,
        v_li->>'line_type',
        v_li->>'description',
        (v_li->>'amount')::numeric,
        COALESCE(v_li->'metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  -- Step 5: Insert EB shares using invoice_index to resolve invoice_id
  IF p_eb_shares IS NOT NULL AND jsonb_array_length(p_eb_shares) > 0 THEN
    FOR v_es IN SELECT * FROM jsonb_array_elements(p_eb_shares)
    LOOP
      v_inv_index := (v_es->>'invoice_index')::int;
      INSERT INTO eb_tenant_shares (
        invoice_id, organization_id, apartment_id, billing_month,
        total_apartment_bill, total_tenant_days, per_day_rate,
        tenant_stay_days, tenant_eb_charge, total_units, unit_cost
      ) VALUES (
        v_inserted_ids[v_inv_index + 1],
        p_org_id,
        (v_es->>'apartment_id')::uuid,
        v_es->>'billing_month',
        (v_es->>'total_apartment_bill')::numeric,
        (v_es->>'total_tenant_days')::int,
        (v_es->>'per_day_rate')::numeric,
        (v_es->>'tenant_stay_days')::int,
        (v_es->>'tenant_eb_charge')::numeric,
        (v_es->>'total_units')::numeric,
        (v_es->>'unit_cost')::numeric
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'count', array_length(v_inserted_ids, 1),
    'invoice_ids', to_jsonb(v_inserted_ids),
    'deleted_count', COALESCE(array_length(v_existing_ids, 1), 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_je_id uuid, p_reason text DEFAULT NULL::text, p_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_orig journal_entries%ROWTYPE;
    v_lines jsonb := '[]'::jsonb;
    v_l    journal_lines%ROWTYPE;
    v_new_id uuid;
BEGIN
    SELECT * INTO v_orig FROM public.journal_entries WHERE id = p_je_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Journal entry % not found', p_je_id;
    END IF;
    IF v_orig.is_reversal_of IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot reverse a reversal entry (%)', p_je_id;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.journal_lines
      WHERE journal_entry_id = p_je_id
    ) THEN
        RAISE EXCEPTION 'Cannot reverse journal entry % because it has no journal lines', p_je_id;
    END IF;

    -- Has it already been reversed by a valid reversal entry?
    IF EXISTS (
      SELECT 1
      FROM public.journal_entries r
      WHERE r.is_reversal_of = p_je_id
        AND EXISTS (
          SELECT 1
          FROM public.journal_lines rjl
          WHERE rjl.journal_entry_id = r.id
        )
    ) THEN
        RAISE EXCEPTION 'Journal entry % has already been reversed', p_je_id;
    END IF;

    -- Flip every line: DR↔CR
    FOR v_l IN
      SELECT *
      FROM public.journal_lines
      WHERE journal_entry_id = p_je_id
      ORDER BY line_no
    LOOP
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'account_id',   v_l.account_id,
            'debit',        v_l.credit,
            'credit',       v_l.debit,
            'party_kind',   v_l.party_kind,
            'party_id',     v_l.party_id,
            'allotment_id', v_l.allotment_id,
            'property_id',  v_l.property_id,
            'apartment_id', v_l.apartment_id,
            'bed_id',       v_l.bed_id,
            'memo',         COALESCE('REVERSAL: ' || v_l.memo, 'REVERSAL')
        ));
    END LOOP;

    v_new_id := public.post_journal_entry(
        v_orig.organization_id,
        COALESCE(p_date, current_date),
        'REVERSAL of ' || COALESCE(v_orig.description, v_orig.id::text)
            || COALESCE(' — ' || p_reason, ''),
        v_orig.source_table,
        v_orig.source_id,
        v_lines,
        jsonb_build_object('reversal_reason', p_reason),
        p_je_id
    );

    RETURN v_new_id;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_adjustment_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF COALESCE(NEW.is_deleted, FALSE) THEN RETURN NEW; END IF;
        v_lines := build_adjustment_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.adjustment_date, current_date),
                NEW.adjustment_type || ' — ' || COALESCE(NEW.reason, NEW.category),
                'tenant_adjustments', NEW.id, v_lines,
                jsonb_build_object('category', NEW.category,
                                   'reference_type', NEW.reference_type)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF COALESCE(NEW.is_deleted, FALSE) AND NOT COALESCE(OLD.is_deleted, FALSE) THEN
            v_existing_je := find_journal_entry_for_source('tenant_adjustments', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'adjustment soft-deleted');
            END IF;
            RETURN NEW;
        END IF;
        IF NOT COALESCE(NEW.is_deleted, FALSE) AND COALESCE(OLD.is_deleted, FALSE) THEN
            v_lines := build_adjustment_lines(NEW.id);
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.adjustment_date, current_date),
                'Adjustment re-posted',
                'tenant_adjustments', NEW.id, v_lines
            );
            RETURN NEW;
        END IF;
        IF NEW.amount IS DISTINCT FROM OLD.amount
           OR NEW.adjustment_type IS DISTINCT FROM OLD.adjustment_type
           OR NEW.category IS DISTINCT FROM OLD.category
        THEN
            v_existing_je := find_journal_entry_for_source('tenant_adjustments', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'adjustment changed');
            END IF;
            v_lines := build_adjustment_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 AND NOT COALESCE(NEW.is_deleted, FALSE) THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.adjustment_date, current_date),
                    'Adjustment corrected',
                    'tenant_adjustments', NEW.id, v_lines
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        -- trg_cascade_je_tenant_adjustments removes journal rows; do not reverse here.
        RETURN OLD;
    END IF;

    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_asset_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_lines := build_asset_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.purchase_date, NEW.invoice_date, NEW.created_at::date, current_date),
                'Asset purchase: ' || COALESCE(NEW.asset_code, NEW.id::text),
                'assets', NEW.id, v_lines,
                jsonb_build_object('asset_code', NEW.asset_code,
                                   'invoice_number', NEW.invoice_number)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.purchase_price IS DISTINCT FROM OLD.purchase_price
           OR NEW.purchase_date IS DISTINCT FROM OLD.purchase_date
           OR NEW.supplier_id   IS DISTINCT FROM OLD.supplier_id
        THEN
            v_existing_je := find_journal_entry_for_source('assets', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'asset changed');
            END IF;
            v_lines := build_asset_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.purchase_date, NEW.invoice_date, NEW.created_at::date, current_date),
                    'Asset purchase (corrected): ' || COALESCE(NEW.asset_code, NEW.id::text),
                    'assets', NEW.id, v_lines
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    RETURN NULL;
END $function$

